use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let intervals: Vec<(i64, i64)> = input.as_array().unwrap()
        .iter()
        .map(|v| (v[0].as_i64().unwrap(), v[1].as_i64().unwrap()))
        .collect();

    let mut events: Vec<(i64, i32)> = intervals.iter()
        .flat_map(|&(start, end)| vec![(start, 1), (end, -1)])
        .collect();

    events.sort();

    let mut max_overlap = 0;
    let mut current_overlap = 0;

    for (_, event) in events {
        current_overlap += event;
        max_overlap = max_overlap.max(current_overlap);
    }

    Value::from(max_overlap)
}
